#include <complex.h>
#include <math.h>
#include <stddef.h>

#define MAX_N 10

typedef struct {
    double re;
    double im;
} cdouble;

static inline double cabs2_(double complex z) {
    double x = creal(z);
    double y = cimag(z);
    return x * x + y * y;
}

static double complex det_minor(const double *a, int n, double complex lambda,
                                int omit_row, int omit_col) {
    double complex m[MAX_N][MAX_N];
    int rows[MAX_N], cols[MAX_N];
    int s = 0;
    for (int i = 0; i < n; ++i) {
        if (i != omit_row) rows[s++] = i;
    }
    s = 0;
    for (int j = 0; j < n; ++j) {
        if (j != omit_col) cols[s++] = j;
    }
    int k = n - 1;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            m[i][j] = a[rows[i] * n + cols[j]];
            if (rows[i] == cols[j]) m[i][j] -= lambda;
        }
    }
    double complex d = 1.0;
    for (int col = 0; col < k; ++col) {
        int pivot = col;
        double best = cabs2_(m[col][col]);
        for (int row = col + 1; row < k; ++row) {
            double q = cabs2_(m[row][col]);
            if (q > best) {
                best = q;
                pivot = row;
            }
        }
        if (best == 0.0) return 0.0;
        if (pivot != col) {
            for (int j = col; j < k; ++j) {
                double complex t = m[col][j];
                m[col][j] = m[pivot][j];
                m[pivot][j] = t;
            }
            d = -d;
        }
        double complex p = m[col][col];
        d *= p;
        for (int row = col + 1; row < k; ++row) {
            double complex f = m[row][col] / p;
            for (int j = col + 1; j < k; ++j) m[row][j] -= f * m[col][j];
        }
    }
    return d;
}

static double norm_vec(const double complex *v, int n) {
    double s = 0.0;
    for (int i = 0; i < n; ++i) s += cabs2_(v[i]);
    return sqrt(s);
}

static double residual(const double *a, int n, double complex lambda,
                       const double complex *v) {
    double s = 0.0;
    for (int i = 0; i < n; ++i) {
        double complex q = -lambda * v[i];
        for (int j = 0; j < n; ++j) q += a[i * n + j] * v[j];
        s += cabs2_(q);
    }
    return sqrt(s);
}

static int normalize(double complex *v, int n) {
    double scale = norm_vec(v, n);
    if (!(scale > 0.0) || !isfinite(scale)) return 0;
    for (int i = 0; i < n; ++i) v[i] /= scale;
    return 1;
}

static int null_vector(const double *a, int n, double complex lambda,
                      double complex *out) {
    double complex m[MAX_N][MAX_N];
    int pivot_col[MAX_N];
    int rank = 0;
    double scale = 0.0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            m[i][j] = a[i * n + j];
            if (i == j) m[i][j] -= lambda;
            double z = cabs2_(m[i][j]);
            if (z > scale) scale = z;
        }
    }
    double tol = sqrt(scale) * 1e-12;
    if (!(tol > 0.0)) tol = 1e-14;

    for (int col = 0; col < n && rank < n; ++col) {
        int pivot = rank;
        double best = cabs2_(m[rank][col]);
        for (int row = rank + 1; row < n; ++row) {
            double z = cabs2_(m[row][col]);
            if (z > best) {
                best = z;
                pivot = row;
            }
        }
        if (sqrt(best) <= tol) continue;
        if (pivot != rank) {
            for (int j = col; j < n; ++j) {
                double complex t = m[rank][j];
                m[rank][j] = m[pivot][j];
                m[pivot][j] = t;
            }
        }
        pivot_col[rank] = col;
        double complex p = m[rank][col];
        for (int row = rank + 1; row < n; ++row) {
            double complex f = m[row][col] / p;
            m[row][col] = 0.0;
            for (int j = col + 1; j < n; ++j) m[row][j] -= f * m[rank][j];
        }
        ++rank;
    }
    if (rank == n) return 0;

    for (int i = 0; i < n; ++i) out[i] = 0.0;
    int free_col = 0;
    while (free_col < n) {
        int used = 0;
        for (int i = 0; i < rank; ++i) if (pivot_col[i] == free_col) used = 1;
        if (!used) break;
        ++free_col;
    }
    if (free_col == n) return 0;
    out[free_col] = 1.0;
    for (int i = rank - 1; i >= 0; --i) {
        int col = pivot_col[i];
        double complex s = 0.0;
        for (int j = col + 1; j < n; ++j) s += m[i][j] * out[j];
        out[col] = -s / m[i][col];
    }
    return normalize(out, n);
}

static int polynomial_vector(const double *a, int n, const cdouble *values,
                            int target, double complex *out) {
    double complex p[MAX_N][MAX_N], q[MAX_N][MAX_N];
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) p[i][j] = (i == j) ? 1.0 : 0.0;
    }
    for (int k = 0; k < n; ++k) {
        if (k == target) continue;
        double complex z = values[k].re + I * values[k].im;
        double peak = 0.0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double complex t = -z * p[i][j];
                for (int l = 0; l < n; ++l) t += a[i * n + l] * p[l][j];
                q[i][j] = t;
                double ab = cabs(t);
                if (ab > peak) peak = ab;
            }
        }
        if (!(peak > 0.0) || !isfinite(peak)) return 0;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) p[i][j] = q[i][j] / peak;
    }
    int best = 0;
    double best_norm = -1.0;
    for (int j = 0; j < n; ++j) {
        double s = 0.0;
        for (int i = 0; i < n; ++i) s += cabs2_(p[i][j]);
        if (s > best_norm) {
            best_norm = s;
            best = j;
        }
    }
    if (!(best_norm > 0.0)) return 0;
    for (int i = 0; i < n; ++i) out[i] = p[i][best];
    return normalize(out, n);
}

static int cofactor_vector(const double *a, int n, double complex lambda,
                           double complex *out) {
    double complex best[MAX_N];
    double best_norm = -1.0;
    for (int row = 0; row < n; ++row) {
        double s = 0.0;
        for (int col = 0; col < n; ++col) {
            double complex z = det_minor(a, n, lambda, row, col);
            if ((row + col) & 1) z = -z;
            out[col] = z;
            s += cabs2_(z);
        }
        if (s > best_norm) {
            best_norm = s;
            for (int col = 0; col < n; ++col) best[col] = out[col];
        }
    }
    if (!(best_norm > 0.0)) return 0;
    for (int i = 0; i < n; ++i) out[i] = best[i];
    return normalize(out, n);
}

void dominant_vector(const double *a, int n, const cdouble *values, int target,
                    cdouble *result) {
    double complex v_poly[MAX_N], v_cof[MAX_N], v_null[MAX_N];
    double complex lambda = values[target].re + I * values[target].im;
    int have_poly = polynomial_vector(a, n, values, target, v_poly);
    int have_cof = cofactor_vector(a, n, lambda, v_cof);
    int have_null = null_vector(a, n, lambda, v_null);

    double complex *best = NULL;
    double best_res = INFINITY;
    if (have_poly) {
        double r = residual(a, n, lambda, v_poly);
        if (isfinite(r) && r < best_res) { best_res = r; best = v_poly; }
    }
    if (have_cof) {
        double r = residual(a, n, lambda, v_cof);
        if (isfinite(r) && r < best_res) { best_res = r; best = v_cof; }
    }
    if (have_null) {
        double r = residual(a, n, lambda, v_null);
        if (isfinite(r) && r < best_res) { best_res = r; best = v_null; }
    }
    if (best == NULL) {
        for (int i = 0; i < n; ++i) result[i] = (i == 0) ? 1.0 : 0.0;
    } else {
        for (int i = 0; i < n; ++i) {
            result[i].re = creal(best[i]);
            result[i].im = cimag(best[i]);
        }
        return;
    }
    for (int i = 0; i < n; ++i) {
        result[i].re = creal(result[i].re + I * result[i].im);
        result[i].im = cimag(result[i].re + I * result[i].im);
    }
}

